{
  "packet_id": "H6-T04-3",
  "claim_id": "C047",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C047.component",
    "value": "Conclusions depend on interview selection.",
    "scope": "Limitations arising from which customers are interviewed.",
    "provenance": {
      "refs": [
        {
          "source_id": "P030",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The mapping explicitly identifies interview selection as a dependency of conclusions."
    }
  },
  "signal_basis": {
    "component_id": "C047.signal_basis",
    "value": "Recontact consenting customers across different event paths and use evidence supporting or contradicting competing explanations to update their relative plausibility.",
    "scope": "Interview-derived evidence from sampled publishers and non-publishers concerning publication intentions, available information, offline preparation and stopping points.",
    "provenance": {
      "refs": [
        {
          "source_id": "P007",
          "role": "SUPPORT"
        },
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P023",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans specify customer selection, the evidence sought and its use in revising explanations."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C047.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The supported limitation requires no unresolved empirical relation."
    }
  },
  "rationale": "Which customers are interviewed determines which experiences and mechanisms enter the interview evidence. Sampling across event paths provides breadth but does not remove this dependency, even when execution succeeds and discriminating observations occur.",
  "uncertainty": "The claim establishes a dependency; it does not establish that selection actually biased any particular conclusion or quantify its effect.",
  "anomalies": []
}
